import json
def std(k,p,h): return f"<ul><li><strong>Pre koho:</strong> {k}</li><li><strong>Použitie:</strong> {p}</li><li><strong>Hlavné prínosy:</strong> {h}</li></ul>"
R=[]
def add(code,name,desc): R.append({"code":code,"nameSk":name,"descriptionSk":desc})
AIR=lambda: std("domácnosť, kancelária, kúpeľňa","rozprášiť do vzduchu zo vzdialenosti","rýchle osvieženie, príjemná vôňa, {v}")
def air(code,name,lead,v): add(code,name,f"<p>{lead}</p>"+std("domácnosť, kancelária, kúpeľňa","rozprášiť do vzduchu zo vzdialenosti",f"rýchle osvieženie, príjemná vôňa, {v}"))
def refill(code,name,lead,v,h=None): add(code,name,f"<p>{lead}</p>"+std("domácnosť","vložiť do kompatibilného osviežovača podľa návodu",h or f"príjemná vôňa, {v}"))
def paste(code,name,lead,v): add(code,name,f"<p>{lead}</p>"+std("každodenná starostlivosť o chrup","čistiť zuby dvakrát denne",f"starostlivosť o zuby, sviežy dych, {v}"))
def massage(code,name,lead,v): add(code,name,f"<p>{lead}</p>"+std("športovci, unavené svaly a kĺby","votrieť do postihnutých partií",f"masáž, uvoľnenie, tradičné zloženie, {v}"))
def bathsalt(code,name,lead,h): add(code,name,f"<p>{lead}</p>"+std("relaxačný kúpeľ","rozpustiť vo vani s teplou vodou",h))

